			long f = p.mods.flags;
			if (((Flags.INTERFACE | Flags.ENUM) & f) != 0) return true;
		}

	}
	JCModifiers mods = getModifiers();
	return mods != null && (Flags.FINAL & mods.flags) != 0;
}

