/**
 * Builds a (possibly qualified, parameterized, annotated) type reference for {@code typeName}
 * in the context of {@code parentType}. Nested types walk their enclosing declarations so that
 * instance inner classes keep outer type parameters and static nested types do not.
 */
public JCExpression namePlusTypeParamsToTypeReference(JavacTreeMaker maker, JavacNode parentType, Name typeName, boolean instance, com.sun.tools.javac.util.List<JCTypeParameter> params, com.sun.tools.javac.util.List<JCAnnotation> annotations) {
	JavacTreeMaker localMaker = this.treeMaker;
	JavacTreeMaker effectiveMaker = maker != null ? maker : localMaker;
	if (effectiveMaker.getUnderlyingTreeMaker() == null) {
		effectiveMaker = localMaker;
	}

	JCExpression r = null;
	if (parentType != null && parentType.getKind() == Kind.TYPE) {
		JavacAST parentAst = parentType.getAst();
		JCTree parentTree = parentType.get();
		if (parentAst != null && parentTree instanceof JCClassDecl) {
			JCClassDecl td = (JCClassDecl) parentTree;
			JCModifiers mods = td.mods;
			long flags = mods.flags;
			Name tdName = td.name;
			if (tdName == null && td.pos == -1) tdName = typeName;
			com.sun.tools.javac.util.List<JCTypeParameter> typarams = td.typarams;
			if (tdName != null && tdName.length() != 0) {
				boolean outerInstance = instance && ((flags & Flags.STATIC) == 0);
				com.sun.tools.javac.util.List<JCTypeParameter> outerParams = instance ? typarams : com.sun.tools.javac.util.List.<JCTypeParameter>nil();
				JavacNode outerParent = parentType.up();
				r = namePlusTypeParamsToTypeReference(effectiveMaker, outerParent, tdName, outerInstance, outerParams, com.sun.tools.javac.util.List.<JCAnnotation>nil());
			}
		}
	}

	r = r == null ? effectiveMaker.Ident(typeName) : effectiveMaker.Select(r, typeName);
	if (annotations != null && !annotations.isEmpty()) r = effectiveMaker.AnnotatedType(annotations, r);
	if (params != null && !params.isEmpty()) {
		ListBuffer<JCExpression> typeArgs = new ListBuffer<JCExpression>();
		for (JCTypeParameter param : params) {
			Name paramName = param.name;
			typeArgs.append(effectiveMaker.Ident(paramName));
		}
		r = effectiveMaker.TypeApply(r, typeArgs.toList());
	}
	return r;
}

